1	//! Exactly-once delivery support for the Kafka sink.
2	//!
3	//! Implements the watermark mechanics behind the `Sink` idempotency hooks: a
4	//! transactional producer commits each page's records plus a commit-token
5	//! record into a compacted side-topic in one Kafka transaction, and the token
6	//! is read back on resume. See
7	//! `docs/superpowers/specs/2026-06-18-kafka-sink-exactly-once-design.md`.
8	
9	use crate::config::KafkaSinkConfig;
10	use faucet_core::FaucetError;
11	use rdkafka::admin::{AdminClient, AdminOptions, NewTopic, TopicReplication};
12	use rdkafka::client::DefaultClientContext;
13	use rdkafka::consumer::{BaseConsumer, Consumer};
14	use rdkafka::error::{KafkaError, RDKafkaErrorCode};
15	use rdkafka::producer::{FutureProducer, FutureRecord, Producer};
16	use rdkafka::{ClientConfig, Message, Offset, TopicPartitionList};
17	use std::time::Duration;
18	
19	/// Build the shared connection `ClientConfig` (brokers + auth) reused by the
20	/// producer, the transactional producer, the admin client, and the
21	/// token-reader consumer. Only keys valid for every client type live here.
22	///
23	/// Producer-only keys (compression, buffering, idempotence) and the
24	/// `extra_client_config` overrides are layered on by the producer builders —
25	/// applying them here would let a producer-only property reach a consumer or
26	/// admin client and be rejected at create time.
27	pub(crate) fn client_config_base(config: &KafkaSinkConfig) -> Result<ClientConfig, FaucetError> {
28	    let mut cfg = ClientConfig::new();
29	    cfg.set("bootstrap.servers", &config.brokers);
30	    config.auth.apply(&mut cfg)?;
31	    Ok(cfg)
32	}
33	
34	/// Full producer `ClientConfig`: the connection base plus producer tuning
35	/// (`acks`, idempotence, compression, linger, message timeout, buffer cap) and
36	/// the user's `extra_client_config` overrides (applied last so they win). Used
37	/// by both the at-least-once producer and the transactional producer; the
38	/// latter then force-sets the transactional invariants on top.
39	pub(crate) fn producer_client_config(
40	    config: &KafkaSinkConfig,
41	) -> Result<ClientConfig, FaucetError> {
42	    let mut cfg = client_config_base(config)?;
43	    cfg.set("acks", config.acks.as_str());
44	    cfg.set(
45	        "enable.idempotence",
46	        if config.idempotent { "true" } else { "false" },
47	    );
48	    cfg.set("compression.type", config.compression.as_str());
49	    cfg.set("linger.ms", config.linger.as_millis().to_string());
50	    cfg.set(
51	        "message.timeout.ms",
52	        config.message_timeout.as_millis().to_string(),
53	    );
54	    if config.batch_size > 0 {
55	        cfg.set(
56	            "queue.buffering.max.messages",
57	            config.batch_size.to_string(),
58	        );
59	    }
60	    for (k, v) in &config.extra_client_config {
61	        cfg.set(k, v);
62	    }
63	    Ok(cfg)
64	}
65	
66	/// Auto-create the compacted commit-token side-topic if it does not exist.
67	/// Idempotent: an "already exists" result is treated as success.
68	pub(crate) async fn ensure_commit_topic(
69	    config: &KafkaSinkConfig,
70	    base: &ClientConfig,
71	) -> Result<(), FaucetError> {
72	    let admin: AdminClient<DefaultClientContext> = base
73	        .create()
74	        .map_err(|e| FaucetError::Sink(format!("kafka admin client init: {e}")))?;
75	    let topic = NewTopic::new(
76	        &config.commit_token_topic,
77	        config.commit_token_topic_partitions,
78	        TopicReplication::Fixed(config.commit_token_topic_replication),
79	    )
80	    .set("cleanup.policy", "compact");
81	    let results = admin
82	        .create_topics([&topic], &AdminOptions::new())
83	        .await
84	        .map_err(|e| FaucetError::Sink(format!("kafka create_topics request: {e}")))?;
85	    for r in results {
86	        match r {
87	            Ok(_) => {}
88	            Err((_t, RDKafkaErrorCode::TopicAlreadyExists)) => {}
89	            Err((t, code)) => {
90	                return Err(FaucetError::Sink(format!(
91	                    "kafka create commit-token topic '{t}': {code:?}"
92	                )));
93	            }
94	        }
95	    }
96	    Ok(())
97	}
98	
99	/// Read the latest committed token for `scope` from the compacted side-topic.
100	/// Returns `None` when the topic is empty or has no token for the scope.
101	///
102	/// Builds a short-lived, non-committing consumer, assigns every side-topic
103	/// partition from the beginning, and drains up to each partition's high
104	/// watermark, folding each record into a running max and discarding it. Memory
105	/// is O(1) in the side-topic size, so a large or non-compacted topic cannot
106	/// blow up the startup read. Called once per run (at startup).
107	pub(crate) async fn read_last_token(
108	    config: &KafkaSinkConfig,
109	    base: &ClientConfig,
110	    scope: &str,
111	) -> Result<Option<String>, FaucetError> {
112	    let mut cfg = base.clone();
113	    cfg.set("group.id", "faucet-commit-token-reader");
114	    cfg.set("enable.auto.commit", "false");
115	    cfg.set("auto.offset.reset", "earliest");
116	    // The side-topic is written by a transactional producer, so we must only
117	    // read committed records — `read_committed` also makes `fetch_watermarks`
118	    // return the Last Stable Offset, keeping the drain target consistent with
119	    // what `poll` delivers. librdkafka defaults to this, but it is load-bearing
120	    // for exactly-once correctness, so pin it explicitly.
121	    cfg.set("isolation.level", "read_committed");
122	    let topic = config.commit_token_topic.clone();
123	    let scope = scope.to_string();
124	    let timeout = config.message_timeout;
125	
126	    tokio::task::spawn_blocking(move || read_last_token_blocking(&cfg, &topic, &scope, timeout))
127	        .await
128	        .map_err(|e| FaucetError::Sink(format!("kafka token read task: {e}")))?
129	}
130	
131	fn read_last_token_blocking(
132	    cfg: &ClientConfig,
133	    topic: &str,
134	    scope: &str,
135	    timeout: Duration,
136	) -> Result<Option<String>, FaucetError> {
137	    let consumer: BaseConsumer = cfg
138	        .create()
139	        .map_err(|e| FaucetError::Sink(format!("kafka token reader init: {e}")))?;
140	
141	    let metadata = consumer
142	        .fetch_metadata(Some(topic), timeout)
143	        .map_err(|e| FaucetError::Sink(format!("kafka token reader metadata: {e}")))?;
144	    let topic_meta = match metadata.topics().iter().find(|t| t.name() == topic) {
145	        Some(t) if !t.partitions().is_empty() => t,
146	        _ => return Ok(None),
147	    };
148	
149	    let mut tpl = TopicPartitionList::new();
150	    // (partition_id, high_watermark, is_empty). Under `read_committed`, `high` is
151	    // the Last Stable Offset — the offset *after* the last committed batch, including
152	    // any transaction commit/abort control markers — so the drain target is the
153	    // consumer's fetch *position* reaching `high`, NOT a count of delivered records
154	    // (a commit marker advances the log offset but is never delivered via `poll`).
155	    // `is_empty` (low == high) means the
156	    // partition has no readable records — true on a fresh topic AND on a fully
157	    // compacted partition whose log-start offset advanced past 0; either way it is
158	    // already drained and must never block the loop while we wait on a position
159	    // that will never be reported (nothing is ever fetched there).
160	    let mut ends: Vec<(i32, i64, bool)> = Vec::new();
161	    for p in topic_meta.partitions() {
162	        let (low, high) = consumer
163	            .fetch_watermarks(topic, p.id(), timeout)
164	            .map_err(|e| FaucetError::Sink(format!("kafka token reader watermarks: {e}")))?;
165	        ends.push((p.id(), high, low >= high));
166	        tpl.add_partition_offset(topic, p.id(), Offset::Beginning)
167	            .map_err(|e| FaucetError::Sink(format!("kafka token reader tpl: {e}")))?;
168	    }
169	    consumer
170	        .assign(&tpl)
171	        .map_err(|e| FaucetError::Sink(format!("kafka token reader assign: {e}")))?;
172	
173	    // Per-partition next-fetch position. A partition is drained once its position
174	    // reaches its high watermark (LSO). The consumer advances its position past a
175	    // control marker even though no record is delivered, so position — unlike a
176	    // delivered-record count — converges to `high` exactly. An empty partition has
177	    // nothing to fetch (no position is ever reported), so it counts as drained
178	    // outright.
179	    let position_reached = |consumer: &BaseConsumer, ends: &[(i32, i64, bool)]| -> bool {
180	        let Ok(pos) = consumer.position() else {
181	            return false;
182	        };
183	        ends.iter().all(|(pid, high, is_empty)| {
184	            if *is_empty {
185	                return true;
186	            }
187	            match pos
188	                .find_partition(topic, *pid)
189	                .and_then(|p| match p.offset() {
190	                    Offset::Offset(o) => Some(o),
191	                    _ => None,
192	                }) {
193	                Some(o) => o >= *high,
194	                // Non-empty partition with no fetched position yet ⇒ not drained.
195	                None => false,
196	            }
197	        })
198	    };
199	
200	    // Keep only the running max token for `scope` and a count of records drained
201	    // (for the fail-loud message), never the records themselves — so a
202	    // non-compacted or not-yet-compacted side-topic with an unbounded backlog
203	    // cannot blow up memory at startup. Each polled record is folded in and
204	    // discarded (no key/value allocation in the hot path).
205	    let mut max_token: Option<u64> = None;
206	    let mut drained: u64 = 0;
207	    if position_reached(&consumer, &ends) {
208	        // Every partition empty (or already at its watermark) — nothing to read.
209	        return Ok(None);
210	    }
211	    loop {
212	        match consumer.poll(timeout) {
213	            Some(Ok(msg)) => {
214	                max_token =
215	                    fold_token_for_scope(max_token, msg.key().unwrap_or(&[]), msg.payload(), scope);
216	                drained += 1;
217	                if position_reached(&consumer, &ends) {
218	                    break;
219	                }
220	            }
221	            Some(Err(e)) => {
222	                return Err(FaucetError::Sink(format!("kafka token reader poll: {e}")));
223	            }
224	            // An empty poll means the broker delivered no record within `timeout`.
225	            // The consumer's fetch position still advances past control markers on
226	            // an empty fetch, so re-check it: if every partition has reached its
227	            // high watermark we are genuinely done (the remaining gap to `high` was
228	            // a transaction commit marker, which is never delivered). Only if the
229	            // position has NOT reached the watermark did the broker fail to deliver
230	            // committed data records in time — returning the max found so far could
231	            // yield a token *below* the true committed value, making the pipeline
232	            // re-write already-committed pages and produce duplicates. Fail loudly
233	            // there rather than silently degrading exactly-once.
234	            None => {
235	                if position_reached(&consumer, &ends) {
236	                    break;
237	                }
238	                return Err(FaucetError::Sink(format!(
239	                    "kafka token reader: drained {drained} record(s) but did not reach the high \
240	                     watermark on every partition within the {timeout:?} poll timeout — refusing \
241	                     to return a possibly-stale commit token"
242	                )));
243	            }
244	        }
245	    }
246	
247	    Ok(max_token.map(faucet_core::idempotency::format_token))
248	}
249	
250	/// Derive the producer `transactional.id` from a stable pipeline scope.
251	///
252	/// The result is `"{prefix}.{sanitized}"`, where `sanitized` replaces any
253	/// character outside `[A-Za-z0-9._-]` with `_`. This keeps the id stable across
254	/// restarts of the same pipeline-row (so a restart fences its own zombie) and
255	/// unique across rows/pipelines whose scopes differ after sanitization (so
256	/// distinct pipelines never fence each other). Sanitization is many-to-one, so
257	/// callers must keep their scopes distinct under it; faucet derives scopes from
258	/// the pipeline/row identity (`{name}::{row_id}`), which stay distinct. `prefix`
259	/// is interpolated verbatim — validating it as a legal `transactional.id`
260	/// fragment is the caller's responsibility.
261	pub(crate) fn derive_transactional_id(prefix: &str, scope: &str) -> String {
262	    let sanitized: String = scope
263	        .chars()
264	        .map(|c| {
265	            if c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-') {
266	                c
267	            } else {
268	                '_'
269	            }
270	        })
271	        .collect();
272	    format!("{prefix}.{sanitized}")
273	}
274	
275	/// Fold one side-topic record into a running maximum commit-token value for
276	/// `scope`.
277	///
278	/// Returns the updated running max: the record's token replaces `running` only
279	/// when its key equals `scope`, its value parses as a commit token, and that
280	/// token exceeds the current `running`. A tombstone (no value), a non-token
281	/// value, or a record for a different scope leaves `running` unchanged. This is
282	/// O(1) per record, so the reader keeps a single running max instead of
283	/// buffering the whole side-topic — bounding memory regardless of topic size on
284	/// a non-compacted (or not-yet-compacted) `commit_token_topic`.
285	pub(crate) fn fold_token_for_scope(
286	    running: Option<u64>,
287	    key: &[u8],
288	    value: Option<&[u8]>,
289	    scope: &str,
290	) -> Option<u64> {
291	    if key != scope.as_bytes() {
292	        return running;
293	    }
294	    let Some(token) = value
295	        .and_then(|v| std::str::from_utf8(v).ok())
296	        .and_then(faucet_core::idempotency::parse_token)
297	    else {
298	        return running;
299	    };
300	    Some(running.map_or(token, |cur| cur.max(token)))
301	}
302	
303	/// Enqueue one record into the current transaction, retrying on `QueueFull`.
304	///
305	/// Unlike the at-least-once `send_with_queue_full_retry`, this does NOT await
306	/// the delivery future: inside a transaction, delivery only completes at
307	/// `commit_transaction`, so awaiting here would deadlock. Errors surface at
308	/// commit time.
309	pub(crate) async fn enqueue_in_txn(
310	    producer: &FutureProducer,
311	    topic: &str,
312	    value_bytes: Vec<u8>,
313	    key_bytes: Option<Vec<u8>>,
314	    partition: Option<i32>,
315	    max_retries: u32,
316	    backoff: Duration,
317	) -> Result<(), FaucetError> {
318	    let mut attempts: u32 = 0;
319	    loop {
320	        let mut record: FutureRecord<'_, [u8], [u8]> =
321	            FutureRecord::to(topic).payload(value_bytes.as_slice());
322	        if let Some(k) = key_bytes.as_deref() {
323	            record = record.key(k);
324	        }
325	        if let Some(p) = partition {
326	            record = record.partition(p);
327	        }
328	        match producer.send_result(record) {
329	            Ok(_delivery_future) => return Ok(()),
330	            Err((KafkaError::MessageProduction(RDKafkaErrorCode::QueueFull), _)) => {
331	                if attempts >= max_retries {
332	                    return Err(FaucetError::Sink(format!(
333	                        "kafka send: QueueFull after {max_retries} retries"
334	                    )));
335	                }
336	                tracing::warn!(attempts, "kafka send: QueueFull, backing off");
337	                tokio::time::sleep(backoff).await;
338	                attempts += 1;
339	            }
340	            Err((e, _)) => return Err(FaucetError::Sink(format!("kafka send: {e}"))),
341	        }
342	    }
343	}
344	
345	/// Abort the current transaction (best-effort, on the blocking pool).
346	pub(crate) async fn abort_txn(
347	    producer: std::sync::Arc<FutureProducer>,
348	    timeout: Duration,
349	) -> Result<(), FaucetError> {
350	    tokio::task::spawn_blocking(move || producer.abort_transaction(timeout))
351	        .await
352	        .map_err(|e| FaucetError::Sink(format!("kafka abort task: {e}")))?
353	        .map_err(|e| FaucetError::Sink(format!("kafka abort_transaction: {e}")))
354	}
355	
356	#[cfg(test)]
357	mod tests {
358	    use super::*;
359	
360	    #[test]
361	    fn base_config_sets_brokers_only() {
362	        use crate::config::{Acks, KafkaSinkConfig, KafkaSinkTopic};
363	        use faucet_common_kafka::{CompressionType, KafkaAuth, KafkaValueFormat, OnKeyError};
364	        use std::collections::BTreeMap;
365	        use std::time::Duration;
366	
367	        let config = KafkaSinkConfig {
368	            brokers: "host:9092".into(),
369	            topic: KafkaSinkTopic::Fixed { name: "out".into() },
370	            auth: KafkaAuth::None,
371	            value_format: KafkaValueFormat::Json,
372	            key_format: None,
373	            value_schema: None,
374	            key_schema: None,
375	            key_path: None,
376	            partition_path: None,
377	            headers_path: None,
378	            on_key_error: OnKeyError::Fail,
379	            compression: CompressionType::None,
380	            acks: Acks::All,
381	            idempotent: true,
382	            linger: Duration::from_millis(5),
383	            batch_size: faucet_core::DEFAULT_BATCH_SIZE,
384	            message_timeout: Duration::from_secs(30),
385	            max_in_flight: 100,
386	            queue_full_backoff: Duration::from_millis(100),
387	            queue_full_max_retries: 3,
388	            transactional_id_prefix: None,
389	            commit_token_topic: "__faucet_commit_token".into(),
390	            commit_token_topic_partitions: 1,
391	            commit_token_topic_replication: -1,
392	            extra_client_config: BTreeMap::new(),
393	        };
394	        let cfg = client_config_base(&config).unwrap();
395	        assert_eq!(cfg.get("bootstrap.servers"), Some("host:9092"));
396	        // compression is producer-only — layered by new(), not by the base.
397	        assert_eq!(cfg.get("compression.type"), None);
398	    }
399	
400	    #[test]
401	    fn derive_sanitizes_scope_separators() {
402	        assert_eq!(
403	            derive_transactional_id("faucet", "pipe::row0"),
404	            "faucet.pipe__row0"
405	        );
406	    }
407	
408	    #[test]
409	    fn derive_keeps_allowed_chars_and_prefix() {
410	        assert_eq!(derive_transactional_id("acme", "a.b-c_1"), "acme.a.b-c_1");
411	        assert_eq!(derive_transactional_id("faucet", "x/y z"), "faucet.x_y_z");
412	    }
413	
414	    #[test]
415	    fn fold_returns_none_without_a_matching_scope() {
416	        let tok = |n| faucet_core::idempotency::format_token(n).into_bytes();
417	        // Only other-scope records seen ⇒ running max stays None (resume from start).
418	        let mut acc = None;
419	        acc = fold_token_for_scope(acc, b"s2", Some(&tok(99)), "s1");
420	        acc = fold_token_for_scope(acc, b"s3", Some(&tok(42)), "s1");
421	        assert_eq!(acc, None);
422	    }
423	
424	    #[test]
425	    fn fold_keeps_running_max_for_scope_only() {
426	        let tok = |n| faucet_core::idempotency::format_token(n).into_bytes();
427	        // Out-of-order tokens for the target scope: running max only grows.
428	        let mut acc = None;
429	        acc = fold_token_for_scope(acc, b"s1", Some(&tok(3)), "s1");
430	        assert_eq!(acc, Some(3));
431	        acc = fold_token_for_scope(acc, b"s1", Some(&tok(7)), "s1");
432	        assert_eq!(acc, Some(7));
433	        // A lower token must not lower the running max.
434	        acc = fold_token_for_scope(acc, b"s1", Some(&tok(5)), "s1");
435	        assert_eq!(acc, Some(7));
436	        // A record for a different scope is ignored (does not perturb the max).
437	        acc = fold_token_for_scope(acc, b"s2", Some(&tok(99)), "s1");
438	        assert_eq!(acc, Some(7));
439	    }
440	
441	    #[test]
442	    fn fold_ignores_tombstones_and_garbage() {
443	        let tok = |n| faucet_core::idempotency::format_token(n).into_bytes();
444	        let mut acc = None;
445	        // Tombstone (no value) for the scope: running max unchanged.
446	        acc = fold_token_for_scope(acc, b"s1", None, "s1");
447	        assert_eq!(acc, None);
448	        // Non-token value for the scope: ignored.
449	        acc = fold_token_for_scope(acc, b"s1", Some(b"not-a-token"), "s1");
450	        assert_eq!(acc, None);
451	        // A valid token then sets it.
452	        acc = fold_token_for_scope(acc, b"s1", Some(&tok(4)), "s1");
453	        assert_eq!(acc, Some(4));
454	    }
455	}
