361	        use ReplayGuarantee::*;
362	        let base = GuaranteeInputs {
363	            replay: Deterministic,
364	            sink_atomic: true,
365	            keyed_upsert_configured: false,
366	            durable_state: true,
367	            dlq: false,
368	        };
