1	//! Per-shard consumer: iterator lifecycle, the `GetRecords` loop,
2	//! throttle-aware backoff, and payload decoding. The pure pieces (backoff
3	//! schedule, iterator-type mapping, record assembly) are separated from the
4	//! I/O loop so they unit-test offline.
5	
6	use crate::config::{KinesisSourceConfig, StartPosition, ValueFormat};
7	use aws_sdk_kinesis::Client;
8	use aws_sdk_kinesis::types::ShardIteratorType;
9	use faucet_core::FaucetError;
10	use serde_json::{Value, json};
11	use std::time::Duration;
12	
13	/// Retry budget for non-throughput `GetRecords`/`GetShardIterator` errors.
14	/// Throughput throttling (`ProvisionedThroughputExceededException`) backs off
15	/// without consuming this budget — it is expected steady-state behavior at
16	/// the 2 MB/s/shard read cap, never an error.
17	pub(crate) const ERROR_RETRY_BUDGET: u32 = 8;
18	
19	/// Exponential backoff with deterministic bounds: `base * 2^attempt`, capped
20	/// at 30 s. Pure — the jitter (0–25%) is applied by the caller from a hash of
21	/// the shard id so tests stay deterministic.
22	pub(crate) fn backoff_delay(base: Duration, attempt: u32) -> Duration {
23	    let cap = Duration::from_secs(30);
24	    let exp = base.saturating_mul(2u32.saturating_pow(attempt.min(16)));
25	    exp.min(cap)
26	}
27	
28	/// Cheap deterministic jitter fraction (0.0–0.25) derived from the shard id,
29	/// so concurrent shards don't thundering-herd after a shared throttle event.
30	pub(crate) fn jitter_fraction(shard_id: &str) -> f64 {
31	    let mut h: u32 = 2166136261;
32	    for b in shard_id.as_bytes() {
33	        h ^= u32::from(*b);
34	        h = h.wrapping_mul(16777619);
35	    }
36	    f64::from(h % 1000) / 4000.0
37	}
38	
39	/// Where a shard's iterator starts: the persisted bookmark wins, else the
40	/// configured start position. Pure.
41	pub(crate) fn iterator_request(
42	    start: &StartPosition,
43	    bookmarked_sequence: Option<&str>,
44	) -> (ShardIteratorType, Option<String>, Option<i64>) {
45	    if let Some(seq) = bookmarked_sequence {
46	        return (
47	            ShardIteratorType::AfterSequenceNumber,
48	            Some(seq.to_string()),
49	            None,
50	        );
51	    }
52	    match start {
53	        StartPosition::TrimHorizon => (ShardIteratorType::TrimHorizon, None, None),
54	        StartPosition::Latest => (ShardIteratorType::Latest, None, None),
55	        StartPosition::AtTimestamp { timestamp_secs } => {
56	            (ShardIteratorType::AtTimestamp, None, Some(*timestamp_secs))
57	        }
58	        StartPosition::AtSequenceNumber { sequence } => (
59	            ShardIteratorType::AtSequenceNumber,
60	            Some(sequence.clone()),
61	            None,
62	        ),
63	        StartPosition::AfterSequenceNumber { sequence } => (
64	            ShardIteratorType::AfterSequenceNumber,
65	            Some(sequence.clone()),
66	            None,
67	        ),
68	    }
69	}
70	
71	/// Decode one Kinesis record payload per the configured format. Pure.
72	pub(crate) fn decode_payload(
73	    data: &[u8],
74	    format: ValueFormat,
75	    shard_id: &str,
76	    sequence: &str,
77	) -> Result<Value, FaucetError> {
78	    match format {
79	        ValueFormat::Json => serde_json::from_slice(data).map_err(|e| {
80	            FaucetError::Source(format!(
81	                "kinesis: record {sequence} in {shard_id} is not valid JSON: {e}"
82	            ))
83	        }),
84	        ValueFormat::String => match std::str::from_utf8(data) {
85	            Ok(s) => Ok(Value::String(s.to_string())),
86	            Err(e) => Err(FaucetError::Source(format!(
87	                "kinesis: record {sequence} in {shard_id} is not valid UTF-8: {e}"
88	            ))),
89	        },
90	        ValueFormat::Bytes => {
91	            use base64::Engine as _;
92	            Ok(Value::String(
93	                base64::engine::general_purpose::STANDARD.encode(data),
94	            ))
95	        }
96	    }
97	}
98	
99	/// Assemble the emitted record: decoded payload + Kinesis metadata. Pure.
100	pub(crate) fn assemble_record(
101	    payload: Value,
102	    partition_key: &str,
103	    sequence: &str,
104	    shard_id: &str,
105	    arrival_ms: Option<i64>,
106	) -> Value {
107	    json!({
108	        "data": payload,
109	        "partition_key": partition_key,
110	        "sequence_number": sequence,
111	        "shard_id": shard_id,
112	        "approximate_arrival_timestamp_ms": arrival_ms,
113	    })
114	}
115	
116	/// A chunk of decoded records from one shard, or the worker's terminal state.
117	#[derive(Debug)]
118	pub(crate) enum ShardEvent {
119	    /// Decoded records + the last sequence number in the chunk.
120	    Records {
121	        shard_id: String,
122	        records: Vec<Value>,
123	        last_sequence: String,
124	    },
125	    /// The shard is fully consumed (closed shard reached its end).
126	    Done { shard_id: String },
127	    /// Unrecoverable failure after the retry budget.
128	    Failed {
129	        shard_id: String,
130	        error: FaucetError,
131	    },
132	}
133	
134	/// Run one shard's consume loop, pushing [`ShardEvent`]s into `tx`. Exits when
135	/// the shard closes, the channel drops (main loop finished), or retries are
136	/// exhausted.
137	pub(crate) async fn run_shard(
138	    client: Client,
139	    config: KinesisSourceConfig,
140	    shard_id: String,
141	    bookmarked_sequence: Option<String>,
142	    tx: tokio::sync::mpsc::Sender<ShardEvent>,
143	) {
144	    let poll_interval = config.poll_interval();
145	    let jitter = jitter_fraction(&shard_id);
146	    let mut last_sequence = bookmarked_sequence.clone();
147	    let mut error_attempts: u32 = 0;
148	
149	    let mut iterator =
150	        match acquire_iterator(&client, &config, &shard_id, last_sequence.as_deref()).await {
151	            Ok(it) => it,
152	            Err(error) => {
153	                let _ = tx.send(ShardEvent::Failed { shard_id, error }).await;
154	                return;
155	            }
156	        };
157	
158	    loop {
159	        let Some(current) = iterator.clone() else {
160	            // NextShardIterator == None → the shard is closed and drained.
161	            let _ = tx.send(ShardEvent::Done { shard_id }).await;
162	            return;
163	        };
164	
165	        match client
166	            .get_records()
167	            .shard_iterator(&current)
168	            .limit(config.records_per_request as i32)
169	            .send()
170	            .await
171	        {
172	            Ok(out) => {
173	                error_attempts = 0;
174	                let records = out.records();
175	                if !records.is_empty() {
176	                    let mut decoded = Vec::with_capacity(records.len());
177	                    for r in records {
178	                        let sequence = r.sequence_number();
179	                        let partition_key = r.partition_key();
180	                        let arrival_ms = r
181	                            .approximate_arrival_timestamp()
182	                            .map(|t| t.to_millis().unwrap_or_default());
183	                        let payload = match decode_payload(
184	                            r.data().as_ref(),
185	                            config.value_format,
186	                            &shard_id,
187	                            sequence,
188	                        ) {
189	                            Ok(p) => p,
190	                            Err(error) => {
191	                                let _ = tx.send(ShardEvent::Failed { shard_id, error }).await;
192	                                return;
193	                            }
194	                        };
195	                        last_sequence = Some(sequence.to_string());
196	                        decoded.push(assemble_record(
197	                            payload,
198	                            partition_key,
199	                            sequence,
200	                            &shard_id,
201	                            arrival_ms,
202	                        ));
203	                    }
204	                    let last = last_sequence.clone().unwrap_or_default();
205	                    if tx
206	                        .send(ShardEvent::Records {
207	                            shard_id: shard_id.clone(),
208	                            records: decoded,
209	                            last_sequence: last,
210	                        })
211	                        .await
212	                        .is_err()
213	                    {
214	                        return; // main loop finished (max_messages / cancel)
215	                    }
216	                }
217	                iterator = out.next_shard_iterator().map(str::to_string);
218	                // Behind records arrive back-to-back; caught-up shards wait
219	                // the poll interval (the 5 reads/sec/shard API budget).
220	                let behind = out.millis_behind_latest().unwrap_or(0);
221	                if records.is_empty() || behind == 0 {
222	                    tokio::time::sleep(poll_interval).await;
223	                }
224	            }
225	            Err(err) => {
226	                let service = err.into_service_error();
227	                if service.is_provisioned_throughput_exceeded_exception() {
228	                    // Expected at the 2 MB/s/shard cap — back off, don't fail.
229	                    let delay = backoff_delay(poll_interval, error_attempts.min(4));
230	                    let delay = delay.mul_f64(1.0 + jitter);
231	                    tracing::debug!(shard = %shard_id, delay_ms = delay.as_millis() as u64,
232	                        "kinesis: throughput exceeded; backing off");
233	                    tokio::time::sleep(delay).await;
234	                    continue;
235	                }
236	                if service.is_expired_iterator_exception() {
237	                    tracing::debug!(shard = %shard_id, "kinesis: iterator expired; re-acquiring");
238	                    match acquire_iterator(&client, &config, &shard_id, last_sequence.as_deref())
239	                        .await
240	                    {
241	                        Ok(it) => {
242	                            iterator = it;
243	                            continue;
244	                        }
245	                        Err(error) => {
246	                            let _ = tx.send(ShardEvent::Failed { shard_id, error }).await;
247	                            return;
248	                        }
249	                    }
250	                }
251	                error_attempts += 1;
252	                if error_attempts >= ERROR_RETRY_BUDGET {
253	                    let _ = tx
254	                        .send(ShardEvent::Failed {
255	                            shard_id: shard_id.clone(),
256	                            error: FaucetError::Source(format!(
257	                                "kinesis: GetRecords on {shard_id} failed after \
258	                                 {ERROR_RETRY_BUDGET} attempts: {service}"
259	                            )),
260	                        })
261	                        .await;
262	                    return;
263	                }
264	                let delay = backoff_delay(poll_interval, error_attempts).mul_f64(1.0 + jitter);
265	                tracing::warn!(shard = %shard_id, error = %service,
266	                    attempt = error_attempts, delay_ms = delay.as_millis() as u64,
267	                    "kinesis: GetRecords failed; retrying");
268	                tokio::time::sleep(delay).await;
269	            }
270	        }
271	    }
272	}
273	
274	/// Acquire a shard iterator at the bookmark (if any) or start position.
275	async fn acquire_iterator(
276	    client: &Client,
277	    config: &KinesisSourceConfig,
278	    shard_id: &str,
279	    bookmarked_sequence: Option<&str>,
