292	        req = req.timestamp(aws_sdk_kinesis::primitives::DateTime::from_secs(secs));
293	    }
294	    let out = req.send().await.map_err(|e| {
295	        FaucetError::Source(format!(
296	            "kinesis: GetShardIterator for {shard_id} failed: {}",
297	            e.into_service_error()
298	        ))
299	    })?;
300	    Ok(out.shard_iterator().map(str::to_string))
301	}
