1	//! Transparent gzip / zstd compression wrappers for file-shaped connectors.
2	//!
3	//! Behind the `compression` feature. Exposes:
4	//! - [`CompressionConfig`] — user-facing enum (`None`, `Gzip`, `Zstd`, `Auto`).
5	//! - [`Compression`] — internal post-resolution enum (no `Auto`).
6	//! - `wrap_async_reader` / `wrap_async_writer` — for `stream_pages` and async sinks.
7	//! - `wrap_sync_reader` / `wrap_sync_writer` — for `spawn_blocking` paths.
8	//! - [`compress_buf`] — one-shot in-memory compression for S3/GCS sink uploads.
9	//! - [`warn_mismatch`] — log-once helper when explicit codec disagrees with the
10	//!   filename extension.
11	
12	use crate::FaucetError;
13	use schemars::JsonSchema;
14	use serde::{Deserialize, Serialize};
15	use std::pin::Pin;
16	use tokio::io::{AsyncBufRead, AsyncWrite};
17	
18	/// User-facing compression config. Defaults to [`Auto`](Self::Auto).
19	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, JsonSchema, Default)]
20	#[serde(rename_all = "lowercase")]
21	pub enum CompressionConfig {
22	    None,
23	    Gzip,
24	    Zstd,
25	    /// Detect from filename suffix: `.gz` → Gzip, `.zst` → Zstd, anything else → None.
26	    #[default]
27	    Auto,
28	}
29	
30	/// Internal post-resolution codec. No `Auto` variant — call [`CompressionConfig::resolve`].
31	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
32	pub enum Compression {
33	    None,
34	    Gzip,
35	    Zstd,
36	}
37	
38	impl CompressionConfig {
39	    /// Resolve `Auto` against a filename. Non-`Auto` variants pass through.
40	    pub fn resolve(self, path: &str) -> Compression {
41	        match self {
42	            Self::None => Compression::None,
43	            Self::Gzip => Compression::Gzip,
44	            Self::Zstd => Compression::Zstd,
45	            Self::Auto => detect_from_path(path),
46	        }
47	    }
48	}
49	
50	/// Codec detection by filename suffix. Case-insensitive. Looks at the final
51	/// extension only: `foo.csv.gz` → Gzip, `foo.gz.zst` → Zstd.
52	pub fn detect_from_path(path: &str) -> Compression {
53	    let lower = path.to_ascii_lowercase();
54	    if lower.ends_with(".gz") {
55	        Compression::Gzip
56	    } else if lower.ends_with(".zst") {
57	        Compression::Zstd
58	    } else {
59	        Compression::None
60	    }
61	}
62	
63	/// Wrap an async buffered reader with a streaming decoder. `None` passes through.
64	pub fn wrap_async_reader<'a, R>(
65	    r: R,
66	    c: Compression,
67	) -> Pin<Box<dyn AsyncBufRead + Send + Unpin + 'a>>
68	where
69	    R: AsyncBufRead + Send + Unpin + 'a,
70	{
71	    match c {
72	        Compression::None => Box::pin(r),
73	        Compression::Gzip => {
74	            let mut dec = async_compression::tokio::bufread::GzipDecoder::new(r);
75	            dec.multiple_members(true);
76	            Box::pin(tokio::io::BufReader::new(dec))
77	        }
78	        // zstd handles concatenated frames natively, so no `multiple_members`-
79	        // equivalent flag is needed (the spec is part of zstd itself).
80	        Compression::Zstd => {
81	            let dec = async_compression::tokio::bufread::ZstdDecoder::new(r);
82	            Box::pin(tokio::io::BufReader::new(dec))
83	        }
84	    }
85	}
86	
87	/// Wrap an async writer with a streaming encoder. `None` passes through.
88	/// Callers must call [`tokio::io::AsyncWriteExt::shutdown`] on the returned
89	/// writer to flush the trailer before the underlying writer is dropped.
90	pub fn wrap_async_writer<'a, W>(
91	    w: W,
92	    c: Compression,
93	) -> Pin<Box<dyn AsyncWrite + Send + Unpin + 'a>>
94	where
95	    W: AsyncWrite + Send + Unpin + 'a,
96	{
97	    match c {
98	        Compression::None => Box::pin(w),
99	        Compression::Gzip => Box::pin(async_compression::tokio::write::GzipEncoder::new(w)),
100	        Compression::Zstd => Box::pin(async_compression::tokio::write::ZstdEncoder::new(w)),
101	    }
102	}
103	
104	/// Wrap a sync reader with a streaming decoder. `None` passes through.
105	pub fn wrap_sync_reader<'a, R>(r: R, c: Compression) -> Box<dyn std::io::Read + Send + 'a>
106	where
107	    R: std::io::Read + Send + 'a,
108	{
109	    match c {
110	        Compression::None => Box::new(r),
111	        Compression::Gzip => Box::new(flate2::read::MultiGzDecoder::new(r)),
112	        Compression::Zstd => Box::new(
113	            zstd::stream::read::Decoder::new(r)
114	                .expect("zstd decoder construction is infallible for any Read"),
115	        ),
116	    }
117	}
118	
119	/// Wrap a sync writer with a streaming encoder. `None` passes through.
120	///
121	/// The returned writer finalises the encoder when dropped (gzip writes its
122	/// 8-byte trailer; zstd's `auto_finish` adapter writes the frame epilogue).
123	/// Because the concrete encoder type is erased behind `Box<dyn Write>`,
124	/// callers cannot invoke `flate2`'s or `zstd`'s `finish()` to capture the
125	/// trailer-write `io::Error`. Callers can `flush()` to drain the encoder's
126	/// internal buffer mid-stream, but trailer-write errors on drop are
127	/// negligibly rare and are silently swallowed.
128	///
129	/// Connectors using this wrapper should drop the box inside a
130	/// `spawn_blocking` task body so the trailer write does not block the
131	/// async runtime, and rely on the surrounding `write_all` / `flush` calls
132	/// to surface earlier I/O errors.
133	pub fn wrap_sync_writer<'a, W>(w: W, c: Compression) -> Box<dyn std::io::Write + Send + 'a>
134	where
135	    W: std::io::Write + Send + 'a,
136	{
137	    match c {
138	        Compression::None => Box::new(w),
139	        Compression::Gzip => Box::new(flate2::write::GzEncoder::new(
140	            w,
141	            flate2::Compression::default(),
142	        )),
143	        Compression::Zstd => Box::new(
144	            zstd::stream::write::Encoder::new(w, 0)
145	                .expect("zstd encoder construction is infallible")
146	                .auto_finish(),
147	        ),
148	    }
149	}
150	
151	/// A sync compressing writer that **retains the concrete encoder** so its
152	/// finalisation error can be captured, unlike the `Box<dyn Write>` returned by
153	/// [`wrap_sync_writer`] (#78/#41).
154	///
155	/// Call [`finish`](Self::finish) when done: it writes the codec's trailer
156	/// (gzip's 8-byte CRC/length footer, zstd's frame epilogue) and returns the
157	/// inner writer, surfacing any I/O error instead of swallowing it on drop.
158	/// If the value is dropped without `finish`, the zstd variant does **not**
159	/// emit its epilogue — always `finish` for a valid stream.
160	pub enum SyncCompressWriter<W: std::io::Write> {
161	    Plain(W),
162	    Gzip(flate2::write::GzEncoder<W>),
163	    Zstd(zstd::stream::write::Encoder<'static, W>),
164	}
165	
166	impl<W: std::io::Write> SyncCompressWriter<W> {
167	    /// Finalise the stream and return the inner writer, propagating any
168	    /// trailer-write error.
169	    pub fn finish(self) -> std::io::Result<W> {
170	        match self {
171	            SyncCompressWriter::Plain(w) => Ok(w),
172	            SyncCompressWriter::Gzip(e) => e.finish(),
173	            SyncCompressWriter::Zstd(e) => e.finish(),
174	        }
175	    }
176	}
177	
178	impl<W: std::io::Write> std::io::Write for SyncCompressWriter<W> {
179	    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
180	        match self {
181	            SyncCompressWriter::Plain(w) => w.write(buf),
182	            SyncCompressWriter::Gzip(e) => e.write(buf),
183	            SyncCompressWriter::Zstd(e) => e.write(buf),
184	        }
185	    }
186	
187	    fn flush(&mut self) -> std::io::Result<()> {
188	        match self {
189	            SyncCompressWriter::Plain(w) => w.flush(),
190	            SyncCompressWriter::Gzip(e) => e.flush(),
191	            SyncCompressWriter::Zstd(e) => e.flush(),
192	        }
193	    }
194	}
195	
196	/// Wrap a sync writer in a [`SyncCompressWriter`] for the given codec. Prefer
197	/// this over [`wrap_sync_writer`] when you need to detect a finalisation
198	/// error: call [`SyncCompressWriter::finish`] before dropping.
199	pub fn sync_compress_writer<W: std::io::Write>(w: W, c: Compression) -> SyncCompressWriter<W> {
200	    match c {
201	        Compression::None => SyncCompressWriter::Plain(w),
202	        Compression::Gzip => SyncCompressWriter::Gzip(flate2::write::GzEncoder::new(
203	            w,
204	            flate2::Compression::default(),
205	        )),
206	        Compression::Zstd => SyncCompressWriter::Zstd(
207	            zstd::stream::write::Encoder::new(w, 0)
208	                .expect("zstd encoder construction is infallible"),
209	        ),
210	    }
211	}
212	
213	/// One-shot in-memory compression. Used by S3 and GCS sinks that build a full
214	/// `Vec<u8>` body before upload.
215	pub fn compress_buf(data: &[u8], c: Compression) -> Result<Vec<u8>, FaucetError> {
216	    use std::io::Write;
217	    match c {
218	        Compression::None => Ok(data.to_vec()),
219	        Compression::Gzip => {
220	            let mut enc = flate2::write::GzEncoder::new(Vec::new(), flate2::Compression::default());
221	            enc.write_all(data)
222	                .map_err(|e| FaucetError::Sink(format!("gzip compress failed: {e}")))?;
223	            enc.finish()
224	                .map_err(|e| FaucetError::Sink(format!("gzip finalise failed: {e}")))
225	        }
226	        Compression::Zstd => zstd::stream::encode_all(data, 0)
227	            .map_err(|e| FaucetError::Sink(format!("zstd compress failed: {e}"))),
228	    }
229	}
230	
231	/// Log a one-shot warning when the explicit codec disagrees with the
232	/// filename's detected codec. Deduplicates per `(path, declared)` pair across
233	/// the whole process so a million-object scan does not flood logs.
234	pub fn warn_mismatch(path: &str, declared: Compression) {
235	    use std::collections::HashSet;
236	    use std::sync::{Mutex, OnceLock};
237	    /// Hard cap on the dedup set so a run touching an unbounded number of
238	    /// *distinct* mismatched paths can't leak memory for the process lifetime
239	    /// (#146 R). Beyond this, mismatches re-warn rather than being tracked —
240	    /// hitting thousands of distinct mismatched paths is already pathological.
241	    const MAX_SEEN: usize = 4096;
242	    static SEEN: OnceLock<Mutex<HashSet<(String, Compression)>>> = OnceLock::new();
243	    let detected = detect_from_path(path);
244	    if detected == declared {
245	        return;
246	    }
247	    let key = (path.to_string(), declared);
248	    let should_warn = {
249	        let mut seen = SEEN
250	            .get_or_init(|| Mutex::new(HashSet::new()))
251	            .lock()
252	            .expect("compression mismatch log mutex poisoned");
253	        if seen.len() >= MAX_SEEN {
254	            true
255	        } else {
256	            seen.insert(key)
257	        }
258	    };
259	    if should_warn {
260	        tracing::warn!(
261	            path = %path,
262	            declared = ?declared,
263	            detected = ?detected,
264	            "compression codec mismatch — explicit config wins, filename extension ignored",
265	        );
266	    }
267	}
