11	/// Map any display-able error into a `FaucetError::Transform` with context.
12	fn te<E: std::fmt::Display>(ctx: &str, e: E) -> FaucetError {
13	    FaucetError::Transform(format!("sql transform: {ctx}: {e}"))
14	}
15	
16	/// Infer an Arrow [`Schema`] from a slice of JSON records.
17	///
18	/// Each element must be a JSON object. Returns the inferred schema wrapped in
19	/// an [`Arc`]. On an empty slice the result is a schema with no fields.
20	pub fn infer_schema(records: &[Value]) -> Result<SchemaRef, FaucetError> {
21	    let iter = records
22	        .iter()
23	        .map(|v| Ok::<_, arrow::error::ArrowError>(v.clone()));
24	    let schema = arrow_json::reader::infer_json_schema_from_iterator(iter)
25	        .map_err(|e| te("schema inference", e))?;
26	    Ok(Arc::new(schema))
27	}
28	
29	/// Encode a slice of JSON records into a single [`RecordBatch`] against `schema`.
30	///
31	/// Uses the `arrow-json` decoder (`ReaderBuilder → build_decoder → serialize →
32	/// flush`). Returns an empty batch if `records` is empty.
33	pub fn json_to_record_batch(
34	    records: &[Value],
35	    schema: SchemaRef,
36	) -> Result<RecordBatch, FaucetError> {
37	    let mut decoder = arrow_json::ReaderBuilder::new(schema.clone())
38	        .build_decoder()
39	        .map_err(|e| te("decoder build", e))?;
40	    decoder.serialize(records).map_err(|e| te("encode", e))?;
41	    let mut batches = Vec::new();
42	    while let Some(b) = decoder.flush().map_err(|e| te("flush", e))? {
43	        batches.push(b);
44	    }
45	    if batches.is_empty() {
46	        return Ok(RecordBatch::new_empty(schema));
47	    }
48	    if batches.len() == 1 {
49	        return Ok(batches.pop().unwrap());
50	    }
51	    arrow::compute::concat_batches(&schema, &batches).map_err(|e| te("concat", e))
52	}
53	
54	/// Decode one or more [`RecordBatch`]es into JSON objects (one per row).
55	///
56	/// Uses `arrow-json`'s [`ArrayWriter`][arrow_json::ArrayWriter], which produces
57	/// a JSON array. An empty input returns an empty `Vec`.
58	pub fn record_batches_to_json(batches: &[RecordBatch]) -> Result<Vec<Value>, FaucetError> {
59	    let mut buf = Vec::new();
60	    {
61	        let mut writer = arrow_json::ArrayWriter::new(&mut buf);
62	        for b in batches {
63	            writer.write(b).map_err(|e| te("json write", e))?;
64	        }
65	        writer.finish().map_err(|e| te("json finish", e))?;
66	    }
67	    let rows: Vec<Value> = serde_json::from_slice(&buf).map_err(|e| te("json parse", e))?;
68	    Ok(rows)
69	}
