    // #321 H5: a running shard's guard must decrement in_flight and drop the
    // shard token on drop (every path), so a Mode-B shard participates in the
    // graceful-shutdown drain and gets a cooperative-flush window.
    use crate::serve::config::{AuthMode, HistoryBackendSpec, ServeConfig};
    use crate::serve::history::RunHistory;
    use crate::serve::history::memory::MemoryHistory;
    use crate::serve::state::ServerState;
