        no_env_file: false,
        log_level: "info".into(),
        ui_enabled: true,
        cluster: crate::serve::cluster::ClusterConfig::disabled(),
        triggers_path: None,
    };
    let history = Arc::new(MemoryHistory::new(Duration::from_secs(60))) as Arc<dyn RunHistory>;
    let state = ServerState::new(
        &cfg,
        None,
        CancellationToken::new(),
        history,
        crate::serve::logs::LogHub::new(),
        None,
        #[cfg(feature = "triggers")]
        crate::serve::triggers::health::TriggersHandle::empty(),
    );

    state
        .registry()
        .register_shard("run", "0", CancellationToken::new());
    state.registry().mark_shard_running();
    assert_eq!(state.registry().in_flight(), 1, "running shard counted");
    {
        let _g = ShardInFlightGuard {
            state: state.clone(),
            run_id: "run".into(),
            shard_id: "0".into(),
        };
    } // guard dropped here
    assert_eq!(state.registry().in_flight(), 0, "guard released the slot");
    assert_eq!(
        state.registry().cancel_run_shards("run"),
        0,
        "guard removed the shard token"
    );
}

