27	impl Registry {
28	    pub fn new(max_queued: usize) -> Self {
29	        Self {
30	            tokens: DashMap::new(),
31	            queued: AtomicUsize::new(0),
32	            in_flight: AtomicUsize::new(0),
33	            max_queued: max_queued.max(1),
