            .split_inclusive([';', '&', '?'])
            .map(|seg| {
                // Preserve any trailing delimiter the split kept on the segment.
                let (body, delim) = match seg.char_indices().next_back() {
                    Some((i, ';' | '&' | '?')) => (&seg[..i], &seg[i..]),
                    _ => (seg, ""),
                };
                match body.find('=') {
                    Some(eq) if is_secret_kv_key(&body[..eq]) => {
                        format!("{}=***{delim}", &body[..eq])
